class CharWidthReader {
    static { this.c = null; }
    static getInstance() {
        if (!CharWidthReader.c) {
            CharWidthReader.c = new CharWidthReader();
        }
        return CharWidthReader.c;
    }
    constructor() {
        this.f = {};
        this.g = document.createElement('canvas');
    }
    getCharWidth(char, font) {
        const cacheKey = char + font;
        if (this.f[cacheKey]) {
            return this.f[cacheKey];
        }
        const context = this.g.getContext('2d');
        context.font = font;
        const metrics = context.measureText(char);
        const width = metrics.width;
        this.f[cacheKey] = width;
        return width;
    }
}
